import{_ as s,o,c as r,a2 as i}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"ADR-0003: Use JWT over Server-Side Sessions","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0003-use-jwt-over-sessions.md","filePath":"adr/0003-use-jwt-over-sessions.md"}'),t={name:"adr/0003-use-jwt-over-sessions.md"};function a(n,e,l,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0003-use-jwt-over-server-side-sessions" tabindex="-1">ADR-0003: Use JWT over Server-Side Sessions <a class="header-anchor" href="#adr-0003-use-jwt-over-server-side-sessions" aria-label="Permalink to &quot;ADR-0003: Use JWT over Server-Side Sessions&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-12 <strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Mozhno — это API-first сервер. Клиенты: React SPA (встроенная веб-панель), Java SDK, JavaScript SDK. SDK-клиенты аутентифицируются по API-ключам (долгоживущие статические токены). Пользователи веб-панели аутентифицируются по email/password.</p><p>Нужен механизм аутентификации, который:</p><ol><li>Не требует sticky sessions при горизонтальном масштабировании.</li><li>Позволяет revoke-токены без централизованного хранилища сессий.</li><li>Поддерживает refresh token rotation с защитой от replay.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>JSON Web Tokens (JWT)</strong> с HMAC-SHA256 подписью для access-токенов и opaque refresh-токенов в БД.</p><ul><li>Access-токен: короткоживущий (15 мин), содержит user_id, email, role, status. Валидируется без запроса к БД.</li><li>Refresh-токен: хранится в БД (таблица <code>refresh_tokens</code>), поддерживает family-based rotation с <code>SELECT ... FOR UPDATE</code>. При обнаружении повторного использования — вся family немедленно revoke&#39;ится.</li><li>API-ключи: проверяются прямым поиском в БД через <code>ApiKeyAuthenticationProvider</code>.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Позитивные:</strong></p><ul><li>Stateless: любой инстанс сервера может валидировать access-токен без обращения к БД или shared cache.</li><li>Refresh token rotation с <code>SELECT ... FOR UPDATE</code> защищает от race condition при одновременном refresh с одного токена.</li><li>API-ключи не требуют refresh-логики — SDK просто хранит ключ.</li><li>Нет необходимости в Redis или shared session storage.</li></ul><p><strong>Негативные:</strong></p><ul><li>Нельзя мгновенно отозвать access-токен (только через короткий TTL).</li><li>Refresh-токены требуют БД-запроса при каждом refresh (приемлемо — 1 запрос на ~15 мин).</li><li>JWT payload растёт с числом claims (ограничение 4KB на куки, нерелевантно для Authorization header).</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><ul><li><strong>Server-side sessions (Spring Session + Redis):</strong> Требует Redis, sticky sessions или distributed cache. Избыточен для API-first сервера.</li><li><strong>Opaque tokens:</strong> Каждый запрос требует БД-запроса. JWT даёт zero-DB-lookup для веба и SDK.</li><li><strong>OAuth2/OpenID Connect:</strong> Избыточен для self-hosted сервера. Может быть добавлен как <code>AuthenticationFlowSpi</code> в enterprise-версии.</li></ul>',16)])])}const S=s(t,[["render",a]]);export{p as __pageData,S as default};
